import fs from 'node:fs';
import { execFileSync } from 'node:child_process';

const DEV='https://d21fbe6u80.execute-api.us-east-1.amazonaws.com/dev';
const PROD='https://je3zud66nb.execute-api.us-east-1.amazonaws.com/prod-v2';
const REGION='us-east-1';
const FUNCTIONS={dev:'stashbox-radio-api-dev-v2',prod:'stashbox-radio-api-prod-v2'};
const OUT='radio/docs/diagnostics/ATTEMPT2_DEEP_PARITY.json';
const SONG_FIELDS=['song_name','display_title','artist','album_name','genre','internal_version_name','languages','secondary_genre','release_format','song_origin','audio_url','video_link','enhanced_visuals_enabled','shuffle_visuals','visual_assets','visual_still_duration_seconds','public_track_note','show_public_note','public_video_note','video_setlist','public_visibility','exclusive','explicit','live_recording','featured','specific_product_urls','spotify_url','apple_music_url','youtube_music_url','official_song_page_url','shop_url','mood_tags','internal_notes'];
const ART_FIELDS=['song_artwork_url','song_artwork_16x9_url','song_artwork_9x16_url','song_artwork_3x4_url','song_artwork_4x5_url','song_artwork_21x9_url'];
fs.mkdirSync('radio/docs/diagnostics',{recursive:true});

function token(fn){const raw=execFileSync('aws',['lambda','get-function-configuration','--function-name',fn,'--region',REGION,'--output','json'],{encoding:'utf8'});const v=JSON.parse(raw)?.Environment?.Variables||{};const t=String(v.ADMIN_TOKEN||v.RADIO_ADMIN_TOKEN||'').trim();if(!t)throw new Error(`Missing admin token ${fn}`);return t;}
async function req(url,t=''){const h={Accept:'application/json'};if(t)h['x-admin-token']=t;const r=await fetch(url,{headers:h});const text=await r.text();let b={};try{b=text?JSON.parse(text):{};}catch{b={raw:text};}if(!r.ok)throw new Error(`GET ${url} -> ${r.status}: ${b.error||b.message||text.slice(0,200)}`);return b;}
const list=(b,k)=>Array.isArray(b)?b:(b?.[k]||b?.items||b?.data||[]);
const sk=s=>String(s?.song_key||s?.songKey||'').trim();
const norm=s=>String(s??'').trim().toLowerCase();
const fid=f=>norm(f?.folder_slug||f?.folder_name||f?.folderName);
const aid=a=>String(a?.id||a?.asset_id||'').trim();
const aurl=a=>String(a?.public_url||a?.url||'').trim();
function media(v){v=String(v||'').trim();if(!v)return'';try{const u=new URL(v);const h=u.hostname.toLowerCase();if(h.includes('cloudfront.net')||h.includes('amazonaws.com')||h==='stashbox.com'||h.endsWith('.stashbox.com'))return decodeURIComponent(u.pathname.replace(/^\//,'')).replace(/^radio\/(?:dev\/v2\/|attempt2\/)?/,'radio/');return u.toString();}catch{return v;}}
function stable(v){if(Array.isArray(v))return v.map(stable);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])]));return v;}
function json(v){return JSON.stringify(stable(v));}
function normValue(field,v){if(['audio_url','video_link'].includes(field))return media(v);if(field==='visual_assets'&&Array.isArray(v))return v.map(x=>({type:String(x?.type||x?.asset_type||x?.media_type||''),media:media(x?.url||x?.src||x?.public_url||''),ratio:String(x?.ratio_label||x?.ratio||'')}));return v;}
function songComparable(s){return Object.fromEntries(SONG_FIELDS.map(f=>[f,normValue(f,s?.[f])]).filter(([,v])=>v!==undefined));}
function assetComparable(a){return {media:media(a?.s3_key||a?.key||aurl(a)),type:String(a?.asset_type||a?.type||''),file_name:String(a?.file_name||a?.filename||''),ratio_label:String(a?.ratio_label||''),caption:String(a?.caption||''),alt_text:String(a?.alt_text||''),notes:String(a?.notes||''),status:String(a?.status||'active')};}
function folderComparable(f){return {folder_name:String(f?.folder_name||''),folder_type:String(f?.folder_type||''),description:String(f?.description||''),status:String(f?.status||''),priority:String(f?.priority||''),notes:String(f?.notes||''),relevant_artists:f?.relevant_artists||[],relevant_genres:f?.relevant_genres||[],relevant_moods:f?.relevant_moods||[],relevant_songs:f?.relevant_songs||[]};}
function recipeBody(b){return !b||b.found===false?null:(b.recipe||b.data?.recipe||null);}
function cleanRecipe(v,ctx,key=''){if(Array.isArray(v))return v.map(x=>cleanRecipe(x,ctx,key));if(v&&typeof v==='object'){const o={};for(const [k,x] of Object.entries(v)){if(['updated_at','prepared_artwork_updated_at','created_at'].includes(k))continue;o[k]=cleanRecipe(x,ctx,k);}return o;}if(typeof v==='string'){if(ctx.folders.has(v))return`folder:${ctx.folders.get(v)}`;if(ctx.assets.has(v))return`asset:${ctx.assets.get(v)}`;if(key.includes('url')||key.includes('artwork')||key.includes('src'))return media(v);}return v;}
function mappingComparable(settings,ctx){const fm=(settings?.folder_mappings||[]).map(m=>({folder:ctx.folders.get(String(m.folder_id||m.folderId||''))||String(m.folder_id||m.folderId||''),state:String(m.inclusion_state||m.state||'')})).sort((a,b)=>json(a).localeCompare(json(b)));const am=(settings?.asset_mappings||[]).map(m=>({asset:ctx.assets.get(String(m.asset_id||m.assetId||m.id||''))||String(m.asset_id||m.assetId||m.id||''),scope:String(m.asset_scope||''),state:String(m.inclusion_state||m.state||''),manual_order:m.manual_order??m.manualOrder??null})).sort((a,b)=>json(a).localeCompare(json(b)));return {order_mode:String(settings?.order_mode||'random'),folder_mappings:fm,asset_mappings:am};}

async function snap(base,t){const songs=list(await req(`${base}/admin/songs`,t),'songs');const folders=list(await req(`${base}/radio/admin/visuals/folders`,t),'folders');const folderAssets={};const folderIdMap=new Map();const assetIdMap=new Map();for(const f of folders){const id=String(f.id||'');const identity=fid(f);if(id)folderIdMap.set(id,identity);if(id){const arr=list(await req(`${base}/radio/admin/visuals/folders/${encodeURIComponent(id)}/assets`,t),'assets');folderAssets[identity]=arr;for(const a of arr)if(aid(a))assetIdMap.set(aid(a),media(a?.s3_key||a?.key||aurl(a)));}}
 const perSong={};for(const s of songs){const key=sk(s);if(!key)continue;const enc=encodeURIComponent(key);const art=(await req(`${base}/radio/admin/songs/${enc}/artwork-images`,t)).media||{};const recipe=recipeBody(await req(`${base}/radio/vec/recipe?song_key=${enc}`));const direct=list(await req(`${base}/radio/admin/vec/song-assets?song_key=${enc}`,t),'assets');for(const a of direct)if(aid(a))assetIdMap.set(aid(a),media(a?.s3_key||a?.key||aurl(a)));let settings=null;try{settings=await req(`${base}/radio/admin/songs/${enc}/visual-settings`,t);}catch{}perSong[key]={art,recipe,direct,settings};}
 return {songs,folders,folderAssets,perSong,ctx:{folders:folderIdMap,assets:assetIdMap}};}

const report={started_at:new Date().toISOString(),song_key:{missing:[],extra_visible:[]},song_metadata:[],artwork:[],folders:[],folder_assets:[],direct_assets:[],recipes:[],visual_settings:[],fatal_error:null};
try{const td=token(FUNCTIONS.dev),tp=token(FUNCTIONS.prod);const d=await snap(DEV,td),p=await snap(PROD,tp);const db=new Map(d.songs.map(s=>[norm(sk(s)),s]).filter(([k])=>k)),pb=new Map(p.songs.map(s=>[norm(sk(s)),s]).filter(([k])=>k));report.counts={dev_songs:d.songs.length,prod_songs:p.songs.length,dev_folders:d.folders.length,prod_folders:p.folders.length};report.song_key.missing=[...db.keys()].filter(k=>!pb.has(k));report.song_key.extra_visible=p.songs.filter(s=>norm(s.public_visibility||'visible')==='visible'&&!db.has(norm(sk(s)))).map(sk);
 for(const [k,ds] of db){const ps=pb.get(k);if(!ps)continue;if(json(songComparable(ds))!==json(songComparable(ps)))report.song_metadata.push({song_key:sk(ds),dev:songComparable(ds),prod:songComparable(ps)});const da=d.perSong[sk(ds)]?.art||{},pa=p.perSong[sk(ds)]?.art||{};for(const f of ART_FIELDS){const dv=media(da[f]||(f==='song_artwork_url'?da.song_artwork_1x1_url:'')),pv=media(pa[f]||(f==='song_artwork_url'?pa.song_artwork_1x1_url:''));if(dv!==pv)report.artwork.push({song_key:sk(ds),field:f,dev:dv,prod:pv});}}
 const df=new Map(d.folders.map(f=>[fid(f),f])),pf=new Map(p.folders.map(f=>[fid(f),f]));for(const [id,f] of df){const q=pf.get(id);if(!q){report.folders.push({folder:id,reason:'missing'});continue;}if(json(folderComparable(f))!==json(folderComparable(q)))report.folders.push({folder:id,reason:'metadata',dev:folderComparable(f),prod:folderComparable(q)});const da=(d.folderAssets[id]||[]).map(assetComparable).sort((a,b)=>json(a).localeCompare(json(b))),pa=(p.folderAssets[id]||[]).map(assetComparable).sort((a,b)=>json(a).localeCompare(json(b)));if(json(da)!==json(pa))report.folder_assets.push({folder:id,dev_count:da.length,prod_count:pa.length,dev:da,prod:pa});}for(const [id,f] of pf){if(!df.has(id)&&norm(f.status||'active')==='active')report.folders.push({folder:id,reason:'extra-active'});}
 for(const [k,ds] of db){if(!pb.has(k))continue;const key=sk(ds);const dd=(d.perSong[key]?.direct||[]).map(assetComparable).sort((a,b)=>json(a).localeCompare(json(b))),pd=(p.perSong[key]?.direct||[]).map(assetComparable).sort((a,b)=>json(a).localeCompare(json(b)));if(json(dd)!==json(pd))report.direct_assets.push({song_key:key,dev_count:dd.length,prod_count:pd.length,dev:dd,prod:pd});const dr=cleanRecipe(d.perSong[key]?.recipe,d.ctx),pr=cleanRecipe(p.perSong[key]?.recipe,p.ctx);if(json(dr)!==json(pr))report.recipes.push({song_key:key,dev:dr,prod:pr});const dsx=mappingComparable(d.perSong[key]?.settings,d.ctx),psx=mappingComparable(p.perSong[key]?.settings,p.ctx);if(json(dsx)!==json(psx))report.visual_settings.push({song_key:key,dev:dsx,prod:psx});}
}catch(e){report.fatal_error=e?.stack||e?.message||String(e);}finally{report.finished_at=new Date().toISOString();const n=report.song_key.missing.length+report.song_key.extra_visible.length+report.song_metadata.length+report.artwork.length+report.folders.length+report.folder_assets.length+report.direct_assets.length+report.recipes.length+report.visual_settings.length;report.mismatch_count=n;report.ok=!report.fatal_error&&n===0;fs.writeFileSync(OUT,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({ok:report.ok,mismatch_count:n,counts:report.counts,categories:{missing:report.song_key.missing.length,extra_visible:report.song_key.extra_visible.length,song_metadata:report.song_metadata.length,artwork:report.artwork.length,folders:report.folders.length,folder_assets:report.folder_assets.length,direct_assets:report.direct_assets.length,recipes:report.recipes.length,visual_settings:report.visual_settings.length},fatal_error:report.fatal_error},null,2));}
if(!report.ok)process.exit(2);
